from collections import Counter
def f(grid):
    H,W=len(grid),len(grid[0])
    flat=Counter(v for row in grid for v in row)
    bg=flat.most_common(1)[0][0]
    vlines=[j for j in range(W) if len({grid[i][j] for i in range(H)})==1 and grid[0][j]!=bg]
    hlines=[i for i in range(H) if len(set(grid[i]))==1 and grid[i][0]!=bg]
    if vlines:
        if len(vlines)>=2: tile_cols=list(range(vlines[0]+1, vlines[-1]+1))
        else: tile_cols=list(range(0, vlines[0]+1))
    else: tile_cols=list(range(W))
    if hlines:
        if len(hlines)>=2: tile_rows=list(range(hlines[0]+1, hlines[-1]+1))
        else: tile_rows=list(range(0, hlines[0]+1))
    else: tile_rows=list(range(H))
    th,tw=len(tile_rows),len(tile_cols)
    return [[grid[tile_rows[i%th]][tile_cols[j%tw]] for j in range(W)] for i in range(H)]
